const $=id=>document.getElementById(id),N=32,BACK={when:'home',floor:'when',seat:'floor'};
let S={boot:false,off:0,today:null,av:null,now:null,busy:null,qrl:null,role:null,lay:null,tool:'seat',qsel:'all',qsz:'m',pend:null,scan:null,err:null,cfg:{open:7,close:23},st:0,en:0,menu:false,pref:'auto',u:null,v:'home',fl:'G',pw:false,sel:null,B:[],X:[],img:null,last:null};
function ld(){}
function sv(){}
const dt=n=>{if(n===0&&S.today)return S.today;const x=new Date();x.setDate(x.getDate()+n);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')};
const dl=n=>n==0?'Today':n==1?'Tomorrow':new Date(dt(n)+'T00:00').toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'});
const hl=h=>(h%12||12)+(h<12?' AM':' PM'),tl=h=>hl(h)+' – '+hl(h+1),nowH=()=>new Date().getHours();
const API_BASE=(typeof window!=='undefined'&&window.LIBSEAT_API!==undefined)?window.LIBSEAT_API:'http://localhost:5000';
let TOKEN=null,LOADN=0,AVT=null,layT=null;const DIRTY=new Set(),RESET=new Set();
async function api(path,method,body){let r;try{r=await fetch(API_BASE+path,{method:method||'GET',headers:{'Content-Type':'application/json',...(TOKEN?{Authorization:'Bearer '+TOKEN}:{})},body:body?JSON.stringify(body):undefined})}catch(e){if(typeof navigator!=='undefined'&&navigator.onLine===false)throw{error:'offline',message:'You are offline. Check your connection.'};throw{error:'server_down',message:'Cannot reach the LibSeat server.'}}
 const d=await r.json().catch(()=>({}));if(!r.ok)throw{status:r.status,...d};return d}
function fail(e){if(!e)return;if(e.error==='offline'){S.err='offline';return draw()}if(e.error==='server_down'){S.err='server_down';return draw()}if(e.status===401&&S.u){toast('Your session ended. Please log in again.');return logout()}if(e.status===429)return toast('Too busy. Try again in a moment.');if(e.error==='closed'){S.err='closed';return draw()}if(e.error==='time_passed'){S.err='expired';return draw()}if(e instanceof Error)throw e;toast(e.message||'Something went wrong. Please try again.')}
const HID=()=>{try{return JSON.parse(localStorage.getItem('ls_hide')||'[]')}catch(e){return[]}};
const mapB=b=>({id:b.id,sid:S.u,seat:b.seat_id,date:b.day,start:b.start_min,end:b.end_min,ci:b.status==='checked_in',rel:b.status==='released',st:b.status});
const busyAt=(f,h)=>(S.busy&&S.busy[f]&&S.busy[f].hours[h])||0;
const qrLink=id=>(S.qrl&&S.qrl[id[0]]&&S.qrl[id[0]][id])||'';
function loadSess(){try{TOKEN=localStorage.getItem('ls_tok');S.u=localStorage.getItem('ls_u');const u=localStorage.getItem('ls_url');if(u)S.cfg.url=u}catch(e){}if(!(TOKEN&&S.u&&okId(S.u))){TOKEN=null;S.u=null}}
function saveSess(){try{TOKEN?localStorage.setItem('ls_tok',TOKEN):localStorage.removeItem('ls_tok');S.u?localStorage.setItem('ls_u',S.u):localStorage.removeItem('ls_u')}catch(e){}}
async function loadCfg(){const c=await api('/api/config');S.cfg.open=c.open;S.cfg.close=c.close;S.today=c.today;S.off=c.now_min-rawNow()}
async function loadLayout(){S.lay=await api('/api/layout');S.X=[];for(const f of['G','F'])for(const s of S.lay[f].seats)if(s.blocked)S.X.push(s.id)}
async function loadMine(){const d=await api('/api/bookings/me');const h=HID();S.B=d.bookings.filter(b=>b.status!=='cancelled'&&!h.includes(b.id)).map(mapB)}
const avm=d=>({free:d.free,total:d.total,m:Object.fromEntries(d.seats.map(x=>[x.id,x.status]))});
async function loadAv(){const s=S.st,e=S.en,my=++LOADN;try{const[g,f]=await Promise.all(['G','F'].map(x=>api(`/api/availability?floor=${x}&start=${s}&end=${e}`)));if(my!==LOADN)return;S.av={G:avm(g),F:avm(f)};if(['when','floor','seat'].includes(S.v)&&!S.sel&&!S.menu)draw()}catch(x){fail(x)}}
async function loadNow(){const d=await api('/api/free_now');S.now={G:{free:d.G.free,booked:d.G.booked,blocked:d.G.blocked},F:{free:d.F.free,booked:d.F.booked,blocked:d.F.blocked}}}
async function loadBusy(){try{S.busy=await api('/api/busy')}catch(e){fail(e)}}
function refreshNow(){loadNow().then(()=>{if(S.v==='home'&&!S.sel&&!S.menu)draw()}).catch(fail)}
async function boot(){await loadCfg();await loadLayout();if(isAdmin()){S.B=[]}else{await loadMine();loadNow().then(()=>{if(S.v==='home'&&!S.boot)draw()}).catch(()=>{})}}
const hs=s=>{let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))>>>0;return h};
const zone=t=>t<2?'Quiet zone':t<6?'Reading hall':'Group study',fn=f=>(S.lay&&S.lay[f]&&S.lay[f].name)||(f=='G'?'Ground floor':'First floor');
const isAdmin=()=>S.u==='ADMIN';
const rawNow=()=>{const d=new Date();return d.getHours()*60+d.getMinutes()};
const nowM=()=>(((rawNow()+(S.off||0))%1440)+1440)%1440;
const fm=m=>`${Math.floor(m/60)%12||12}:${String(m%60).padStart(2,'0')} ${Math.floor(m/60)<12?'AM':'PM'}`;
const rg=(a,b)=>fm(a)+' – '+fm(b);
const dh=m=>(m>=60?Math.floor(m/60)+' h':'')+(m%60?(m>=60?' ':'')+m%60+' min':'');
const ov=(a,b,c,d)=>a<d&&c<b;
const seatsOf=f=>S.lay[f].seats,NF=f=>seatsOf(f).length,NT=()=>NF('G')+NF('F'),seatOf=id=>((S.lay&&S.lay[id[0]])||{seats:[]}).seats.find(x=>x.id===id),dv=(a,b)=>b?a/b:0;
function defLayout(){const X0=[34,206],RY=[82,182,282,382],mk=f=>{const seats=[],tables=[];for(let t=0;t<8;t++){const x=X0[t%2],y=RY[t>>1];tables.push({x,y,w:120,h:30});[[10,-24],[70,-24],[10,32],[70,32]].forEach((q,k)=>{const n=t*4+k+1;seats.push({id:f+n,x:x+q[0],y:y+q[1],pw:n%3==0,z:t<2?'Quiet zone':t<6?'Reading hall':'Group study'})})}return{seats,tables,img:null,decor:true}};return{G:mk('G'),F:mk('F')}}
function saveLay(){S.qrl=null;DIRTY.add(S.fl);clearTimeout(layT);layT=setTimeout(pushAll,500)}
async function pushAll(){for(const f of[...DIRTY]){DIRTY.delete(f);await pushLay(f)}}
async function pushLay(f){const L=S.lay[f],reset=RESET.has(f);RESET.delete(f);try{await api('/api/admin/layout/'+f,'PUT',{layout:L,reset_bookings:reset});if(reset)toast('Saved. Bookings on this floor were cancelled.')}catch(e){fail(e);try{await loadLayout()}catch(x){}draw()}}
const col=r=>r<.6?'var(--okb)':r<.9?'var(--am)':'var(--bkb)',lab=r=>r<.6?'Quiet':r<.9?'Filling up':'Almost full';
const mine=id=>S.B.find(b=>b.sid==S.u&&!b.rel&&b.seat==id&&b.date==dt(0)&&ov(b.start,b.end,S.st,S.en));
let tt;function toast(m){const t=$('toast');t.textContent=m;t.className='s';clearTimeout(tt);tt=setTimeout(()=>t.className='',2300)}
const go=v=>{if(v!=='camera')stopCam();S.v=v;draw();scrollTo(0,0);clearInterval(AVT);AVT=null;
 if(S.u&&S.lay&&!S.boot){if(v==='home'&&!isAdmin())refreshNow();
  if(v==='my')loadMine().then(()=>{if(S.v==='my')draw()}).catch(fail);
  if(v==='seat'||v==='floor')AVT=setInterval(()=>{if((S.v==='seat'||S.v==='floor')&&!S.sel&&!S.menu)loadAv()},8000+Math.random()*4000)}};
function lim(){return{lo:Math.max(S.cfg.open*60,Math.ceil(nowM()/15)*15),hi:S.cfg.close*60}}
function fixT(){const{lo,hi}=lim();S.st=Math.min(Math.max(S.st,lo),hi-30);if(S.en<S.st+30)S.en=S.st+60;S.en=Math.min(S.en,hi)}
function start(){if(isAdmin())return;const{lo,hi}=lim();if(lo+30>hi){S.err='closed';return draw()}const cur=S.B.find(b=>b.sid==S.u&&!b.rel&&b.date==dt(0)&&ov(b.start,b.end,nowM(),lo+30));
 if(cur)return showHTML('Seat already reserved','<p>You already have a reserved seat at this time.</p><div class="kv">Seat '+cur.seat+', '+rg(cur.start,cur.end)+'</div><p class="mu sm">Cancel it first if you want a different seat.</p><div class="cacts"><button class="sbtn pbtn" onclick="closeDoc();go(\'my\')">View my bookings</button><button class="sbtn" onclick="closeDoc()">Close</button></div>','cmp');
 S.st=lo;S.en=lo+60;S.pw=false;S.av=null;fixT();go('when');loadAv()}
async function setCfg(k,v){if(k==='url'){S.cfg.url=v||undefined;S.qrl=null;try{v?localStorage.setItem('ls_url',v):localStorage.removeItem('ls_url')}catch(e){}return draw()}
 const o=k==='open'?v:S.cfg.open,c=k==='close'?v:S.cfg.close;try{await api('/api/admin/settings','PUT',{open:o,close:c});S.cfg.open=o;S.cfg.close=c}catch(e){fail(e)}draw()}
const okId=v=>v==='ADMIN'||/^RA\d{13}$/.test(v);
async function login(){const v=$('sid').value.trim().toUpperCase();if(!okId(v))return toast('Not valid. Enter RA followed by 13 digits (15 characters in total).');if(!$('agree').checked)return toast('Please accept the Privacy Notice and Terms to continue');
 try{let d;if(v==='ADMIN'){const pw=($('apw')||{}).value||'';if(!pw)return toast('Enter the admin password');d=await api('/api/admin/login','POST',{username:'admin',password:pw})}else d=await api('/api/login','POST',{reg_no:v});
  TOKEN=d.token;S.u=v==='ADMIN'?'ADMIN':d.reg_no;S.role=d.role;saveSess();try{localStorage.setItem('ls_c',JSON.stringify({v:1,t:new Date().toISOString()}))}catch(e){}
  S.boot=true;draw();await boot();S.boot=false;S.v=isAdmin()?'admin':'home';draw();runPend()}
 catch(e){S.boot=false;if(S.u&&!TOKEN)S.u=null;if(e.error==='invalid_reg_no'||e.error==='bad_credentials'||e.error==='sso_required')toast(e.message);else fail(e);if(!S.u)draw()}}
function logout(){TOKEN=null;S.u=null;S.role=null;S.B=[];S.av=null;S.now=null;S.qrl=null;S.sel=null;S.menu=false;S.last=null;S.v='home';saveSess();draw()}
const sysDark=()=>typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches;
function applyTheme(){document.documentElement.dataset.theme=S.pref==='auto'?(sysDark()?'dark':'light'):S.pref}
function themeDlg(){const themes=[['porcelain','Pure Porcelain'],['oat','Nordic Oat'],['alabaster','Alabaster Light'],['linen','Academic Linen'],['mint','Ceramic Mint'],['rose','Rose Alabaster'],['dark','Dark Slate'],['obsidian','Midnight Obsidian'],['espresso','Warm Espresso'],['cobalt','Midnight Cobalt'],['bordeaux','Bordeaux Velvet']];
 const groups=[['LIGHT',themes.slice(0,6)],['DARK',themes.slice(6)]];
 const opts=`<button class="topt ${S.pref==='auto'?'on':''}" onclick="setTheme('auto');closeDoc()"><b>System (Auto)</b><i>${S.pref==='auto'?'✓':''}</i></button>`+groups.map(([label,items])=>`<h3 class="theme-label">${label}</h3><div class="theme-options">${items.map(([v,name])=>`<button class="topt ${S.pref===v?'on':''}" onclick="setTheme('${v}');closeDoc()"><b>${name}</b><i>${S.pref===v?'✓':''}</i></button>`).join('')}</div>`).join('');
 showHTML('Theme',opts+'<div class="cacts"><button class="sbtn" onclick="closeDoc()">Close</button></div>','cmp')}
function setTheme(t){S.pref=t;applyTheme();try{localStorage.setItem('ls_t',t)}catch(e){}draw()}
function nv(v){S.menu=false;go(v)}
const topbar=()=>`<div class="top"><button onclick="S.menu=true;draw()" aria-label="Menu">☰</button><span class="brand">LibSeat</span><div class="av">${S.u[0]}</div></div>`;
function drawer(){const it=(v,l)=>`<button class="mi ${S.v==v?'on':''}" onclick="nv('${v}')">${l}</button>`;
 const themeNames={auto:'System (Auto)',porcelain:'Pure Porcelain',oat:'Nordic Oat',alabaster:'Alabaster Light',linen:'Academic Linen',mint:'Ceramic Mint',rose:'Rose Alabaster',dark:'Dark Slate',obsidian:'Midnight Obsidian',espresso:'Warm Espresso',cobalt:'Midnight Cobalt',bordeaux:'Bordeaux Velvet'};
 return `<div class="ov dr" onclick="S.menu=false;draw()"><div class="side" onclick="event.stopPropagation()"><button class="xb" onclick="S.menu=false;draw()" aria-label="Close menu"><svg width="18" height="18" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M3 3l12 12M15 3L3 15"/></svg></button><div class="pf"><div class="av">${S.u[0]}</div><b>${S.u}</b><p class="mu sm">${isAdmin()?'Librarian':'Student'}</p></div>${isAdmin()?it('admin','Admin'):it('home','Home')+it('my','My bookings')}<button class="mi" onclick="themeDlg()">Theme<span class="mv">${themeNames[S.pref]}</span></button><p class="zn" style="margin:16px 4px 6px">Privacy</p><button class="mi" onclick="showDoc('privacy')">Privacy Notice</button><button class="mi" onclick="showDoc('terms')">Terms of use</button>${isAdmin()?'':`<button class="mi" onclick="exportData()">View my data</button><button class="mi r2" onclick="delData()">Delete my data</button>`}<button class="mi r" onclick="S.menu=false;logout()">Log out</button></div></div>`}
function pick(id){const st=S.av&&S.av[S.fl]?S.av[S.fl].m[id]:null;if(!st)return toast('Loading seats… try again in a moment.');if(st==='blocked')return toast('This seat is blocked by the library');if(st==='booked')return toast('Seat already booked');
 const my=S.B.find(b=>b.sid==S.u&&!b.rel&&b.date==dt(0)&&ov(b.start,b.end,S.st,S.en));if(my&&my.seat!=id)return toast('You already have a reserved seat at this time');S.sel=id;draw()}
async function book(id){if(S.bk)return;S.bk=true;try{if(S.en<=nowM()){S.sel=null;S.err='expired';return draw()}const r=await api('/api/bookings','POST',{seat:id,start:S.st,end:S.en});await loadMine();S.last={seat:id,start:r.start_min,end:r.end_min,date:r.day,id:r.id};S.sel=null;go('done')}
 catch(e){S.sel=null;if(['seat_taken','already_reserved','limit_reached','seat_blocked'].includes(e.error)){toast(e.message);loadAv()}else fail(e);draw()}finally{S.bk=false}}
async function cancelB(id){const m=mine(id);if(!m)return;try{await api('/api/bookings/'+m.id,'DELETE');await loadMine();S.sel=null;toast('Booking cancelled');await loadAv()}catch(e){fail(e)}draw()}
